import 'package:dierb_api_client/dierb_api_client.dart';
import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
class StoreSettingsScreen extends StatefulWidget{const StoreSettingsScreen({super.key});@override State<StoreSettingsScreen>createState()=>_State();}
class _State extends State<StoreSettingsScreen>{final api=DierbApi(),picker=ImagePicker(),name=TextEditingController(),description=TextEditingController(),phone=TextEditingController(),whatsapp=TextEditingController(),address=TextEditingController();List<dynamic>categories=const[],cities=const[];Map<String,dynamic>?store;String?categoryId,cityId,logo,cover,error;bool loading=true,saving=false,uploading=false;
@override void initState(){super.initState();_load();}@override void dispose(){api.close();name.dispose();description.dispose();phone.dispose();whatsapp.dispose();address.dispose();super.dispose();}
Future<void>_load()async{try{final v=await Future.wait([api.merchantStore(),api.categories(),api.cities()]);final r=Map<String,dynamic>.from(v[0]as Map);store=r['store']is Map?Map<String,dynamic>.from(r['store']as Map):null;categories=v[1]as List;cities=v[2]as List;if(store!=null){name.text=(store!['name']??'').toString();description.text=(store!['description']??'').toString();phone.text=(store!['phone']??'').toString();whatsapp.text=(store!['whatsapp']??'').toString();address.text=(store!['address']??'').toString();categoryId=store!['categoryId']?.toString();cityId=store!['cityId']?.toString();logo=store!['logoUrl']?.toString();cover=store!['coverUrl']?.toString();}else{if(categories.isNotEmpty)categoryId=(categories.first as Map)['id'].toString();if(cities.isNotEmpty)cityId=(cities.first as Map)['id'].toString();}if(mounted)setState(()=>loading=false);}catch(e){if(mounted)setState((){loading=false;error=e is DierbApiException?e.message:'تعذر تحميل المتجر';});}}
Future<void>_image(bool isLogo)async{final x=await picker.pickImage(source:ImageSource.gallery,imageQuality:84,maxWidth:isLogo?900:1800);if(x==null)return;setState(()=>uploading=true);try{final r=await api.uploadImage(await x.readAsBytes(),x.name);setState((){if(isLogo)logo=r['url'].toString();else cover=r['url'].toString();});}catch(e){setState(()=>error=e is DierbApiException?e.message:'تعذر رفع الصورة');}finally{if(mounted)setState(()=>uploading=false);}}
Future<void>_save()async{if(name.text.trim().length<2||phone.text.trim().length<8||address.text.trim().length<5||categoryId==null||cityId==null){setState(()=>error='أكمل اسم المتجر والقسم والهاتف والعنوان');return;}setState((){saving=true;error=null;});final b=<String,dynamic>{'name':name.text.trim(),'description':description.text.trim(),'categoryId':categoryId,'cityId':cityId,'address':address.text.trim(),'phone':phone.text.trim(),'whatsapp':whatsapp.text.trim().isEmpty?phone.text.trim():whatsapp.text.trim(),'logoUrl':logo,'coverUrl':cover,'deliveryEnabled':true,'pickupEnabled':true,'minimumOrderPiasters':0,'deliveryFeePiasters':0};b.removeWhere((_,v)=>v==null||v=='');try{if(store==null)await api.createMerchantStore(b);else await api.updateMerchantStore(b);if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم حفظ بيانات المتجر')));Navigator.pop(context);}}catch(e){if(mounted)setState(()=>error=e is DierbApiException?e.message:'تعذر الحفظ');}finally{if(mounted)setState(()=>saving=false);}}
