,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'الهاتف')),const SizedBox(height:10),TextField(controller:whatsapp,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'واتساب')),const SizedBox(height:10),TextField(controller:address,decoration:const InputDecoration(labelText:'العنوان')),if(error!=null)Padding(padding:const EdgeInsets.only(top:10),child:Text(error!,style:TextStyle(color:Theme.of(context).colorScheme.error))),const SizedBox(height:16),FilledButton.icon(onPressed:saving||uploading?null:_save,icon:saving?const SizedBox.square(dimension:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.save_outlined),label:const Text('حفظ ملف المتجر'))]));}
